CREATE OR REPLACE VIEW god2_research.vw_xjz_client_message_security_simplified_scan_zh_tw AS
SELECT '客戶端訊息模板' AS 資料表, COUNT(*) AS 疑似簡體殘留
FROM god2_research.xjz_client_message_template_evidence
WHERE CONCAT_WS('', text_zh_tw, alt_text_zh_tw, service_label_zh_tw, service_phase_zh_tw) REGEXP '[System.Collections.Specialized.OrderedDictionary+OrderedDictionaryKeyValueCollection]'
UNION ALL
SELECT '聊天命名禁詞', COUNT(*)
FROM god2_research.xjz_forbidden_word_evidence
WHERE CONCAT_WS('', word_text_zh_tw, normalized_key_zh_tw) REGEXP '[System.Collections.Specialized.OrderedDictionary+OrderedDictionaryKeyValueCollection]'
UNION ALL
SELECT '安全阻擋規則', COUNT(*)
FROM god2_research.xjz_client_security_block_rule_evidence
WHERE CONCAT_WS('', pattern_text_zh_tw, note_zh_tw) REGEXP '[System.Collections.Specialized.OrderedDictionary+OrderedDictionaryKeyValueCollection]';

